mapper.select:
select * from ( select a.*,b.machine_name from t_cx_loss_setting a left join T_CX_MACHINE_INFO b on a.machine_code = b.machine_code and b.del_flag = '0' where a.del_flag = '0' and INSTR(a.embryo_code, #{embryoCode}) > 0 and a.machine_code = #{machineCode}
order by a.create_time desc
) t
order by ${orderStr}

select count(1)
from t_cx_loss_setting
where del_flag = '0'
and embryo_code = #{embryoCode}
and embryo_code is null
and machine_code = #{machineCode}
and machine_code is null
and id != #{id}

mapper.update:
update t_cx_loss_setting
embryo_code = #{embryoCode}, machine_code = #{machineCode}, loss_rate = #{lossRate}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, remark = #{remark},
where id = #{id}

mapper.delete:
update t_cx_loss_setting
set del_flag='1'
where id = #{id}
